import { render } from '@solidjs/web';
import { createSignal, flush, For } from 'solid-js';
import './styles.css';

function Log() {
  let list;
  const [entries, setEntries] = createSignal([]);
  const [summary, setSummary] = createSignal('No entries yet');

  const add = () => {
    setEntries((all) => [...all, `Entry ${all.length + 1}`]);
    setSummary(`${entries().length} entries`);
    list.lastElementChild?.scrollIntoView();
  };

  return (
    <>
      <button onClick={add}>Add entry</button> <span>{summary()}</span>
      <ul ref={list}>
        <For each={entries()}>{(entry) => <li>{entry}</li>}</For>
      </ul>
    </>
  );
}

render(() => <Log />, document.getElementById('app'));

ul {
  height: 120px;
  overflow: auto;
  border: 1px solid #ccc;
  font-family: sans-serif;
}

import { render } from '@solidjs/web';
import { createSignal, flush, For } from 'solid-js';
import './styles.css';

function Log() {
  let list;
  const [entries, setEntries] = createSignal([]);
  const summary = () =>
    entries().length ? `${entries().length} entries` : 'No entries yet';

  const add = () => {
    setEntries((all) => [...all, `Entry ${all.length + 1}`]);
    flush();
    list.lastElementChild.scrollIntoView();
  };

  return (
    <>
      <button onClick={add}>Add entry</button> <span>{summary()}</span>
      <ul ref={list}>
        <For each={entries()}>{(entry) => <li>{entry}</li>}</For>
      </ul>
    </>
  );
}

render(() => <Log />, document.getElementById('app'));

ul {
  height: 120px;
  overflow: auto;
  border: 1px solid #ccc;
  font-family: sans-serif;
}
